/****** Object:  View [dbo].[IncassiPerGrafici4]    Script Date: 11/17/2025 15:16:01 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[IncassiPerGrafici4] AS SELECT Incassi.Data,Incassi.Incasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente, Incassi.tipooggetto,Incassi.codiceoggetto,schede.nome as Modello,schede.matricola AS Matricola,'Prontoscheda' AS TIPO  from incassi,schede where incassi.codiceoggetto=schede.idscheda and incassi.tipooggetto=1 UNION SELECT Incassi.Data,Incassi.Incasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente,Incassi.tipooggetto,Incassi.codiceoggetto,dedicati.nome as Modello,dedicati.matricola as Matricola,'New Slot' AS TIPO  from incassi,dedicati  where incassi.codiceoggetto=dedicati.iddedicato and incassi.tipooggetto=2 and dedicati.partipologiamonopoli=1 UNION SELECT Incassi.Data,Incassi.Incasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente,Incassi.tipooggetto,Incassi.codiceoggetto,dedicati.nome as Modello,dedicati.matricola as Matricola,'Gioco' AS TIPO  from incassi,dedicati  where incassi.codiceoggetto=dedicati.iddedicato and incassi.tipooggetto=2  and (dedicati.partipologiamonopoli<>1 or dedicati.partipologiamonopoli is null) UNION SELECT Incassi.Data,Incassi.Incasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente,Incassi.tipooggetto,Incassi.codiceoggetto,distribut.nome as Modello,distribut.matricola AS Matricola,'Distributore' AS TIPO  from incassi,distribut  where incassi.codiceoggetto=distribut.iddistributore and incassi.tipooggetto=15
GO
